/**
 * Company-detail enrichment seed.
 *
 * Adds long-form about prose, foundedYear, LinkedIn URL, benefits,
 * companyTier and expanded techStack / evDomains arrays to each
 * Company row. Idempotent — re-runs upsert by slug and only touch
 * the enrichment columns, preserving everything else (name, ATS
 * settings, ownerUserId, verificationStatus, etc.).
 *
 * Mirrors scripts/seed-institution-enrichment.ts:
 *   • Batched at ~100 companies per file edition.
 *   • Append-only convention — each batch lives in its own const
 *     (BATCH_01, BATCH_02 …). Newer batches go below the existing
 *     ones so the file diff stays clean across reviews.
 *   • Per-field merge: only touch a field if the spec sets it;
 *     existing data wins by default.
 *
 * Run with:
 *   pnpm exec tsx scripts/seed-company-enrichment.ts
 */

import { PrismaClient, CompanyTier } from "@prisma/client";

const db = new PrismaClient();

// ─── Type shape ───────────────────────────────────────────────

interface EnrichmentSpec {
  slug: string;
  /// Long-form prose (~2-4 sentences). Filled into Company.about
  /// only if the existing value is NULL — admin / seed wins on the
  /// next pass. Use for narrative not covered by `description`.
  about?: string;
  /// Year the company was founded. Mostly missing from the bulk
  /// rows in seed.ts — we backfill from Wikipedia / company press.
  foundedYear?: number;
  /// Company LinkedIn URL — surfaces as a chip on /company/[slug]
  /// hero. Always the official "Company" page (not jobs / talent).
  linkedinUrl?: string;
  /// Twitter / X handle URL. Optional.
  twitterUrl?: string;
  /// Facebook page URL. Optional — most B2B-only companies skip it.
  facebookUrl?: string;
  /// Employee headcount band. Falls back to seed.ts value if absent.
  teamSize?: string;
  /// Bulleted perks ("ESOPs", "On-site EV-test rides", etc.).
  /// Rendered as chips on /company/[slug]. Concatenated with any
  /// existing benefits and de-duped before write.
  benefits?: string[];
  /// Skill / framework chips on /company/[slug]. Concatenated +
  /// deduped with existing techStack.
  techStack?: string[];
  /// EV-domain taxonomy chips ("battery-tech", "charging-infra",
  /// "fleet-mobility", "powertrain", "manufacturing", "software-iot",
  /// "policy-research", "vehicle-engineering"). Concatenated +
  /// deduped with existing.
  evDomains?: string[];
  /// First-class tier facet — OEM / TIER1_SUPPLIER / STARTUP /
  /// CHARGING_OPERATOR / RESEARCH_INSTITUTE / CONSULTING / OTHER.
  /// Drives /companies type filter UX.
  companyTier?: CompanyTier;
}

