// ─── Driver ───────────────────────────────────────────────────

async function main() {
  const allBatches: { name: string; specs: EnrichmentSpec[] }[] = [
    { name: "batch 01", specs: BATCH_01 },
    { name: "batch 02", specs: BATCH_02 },
    { name: "batch 03", specs: BATCH_03 },
    { name: "batch 04", specs: BATCH_04 },
    { name: "batch 05", specs: BATCH_05 },
    { name: "batch 06", specs: BATCH_06 },
    { name: "batch 07", specs: BATCH_07 },
    { name: "batch 08", specs: BATCH_08 },
    { name: "batch 09", specs: BATCH_09 },
    { name: "batch 10", specs: BATCH_10 },
    { name: "batch 11", specs: BATCH_11 },
    { name: "batch 12", specs: BATCH_12 },
  ];
  const totalSpecs = allBatches.reduce((acc, b) => acc + b.specs.length, 0);
  console.log(`📚 Enriching ${totalSpecs} companies across ${allBatches.length} batches...`);
  let touched = 0;
  let missing = 0;

  for (const batch of allBatches) {
    console.log(`\n── ${batch.name} (${batch.specs.length} entries) ──`);
    for (const spec of batch.specs) {
      const existing = await db.company.findUnique({
        where: { slug: spec.slug },
        select: {
          id: true,
          name: true,
          about: true,
          foundedYear: true,
          linkedinUrl: true,
          twitterUrl: true,
          facebookUrl: true,
          teamSize: true,
          benefits: true,
          techStack: true,
          evDomains: true,
          companyTier: true,
        },
      });
      if (!existing) {
        console.warn(`   ⚠ Slug not found: ${spec.slug}`);
        missing += 1;
        continue;
      }

      // Per-field merge — only touch a column if the spec sets it,
      // AND for scalar fields, only fill if the existing value is
      // NULL (so admin edits win on re-runs). For array fields,
      // concat + dedupe so we accumulate items across passes.
      const data: Record<string, unknown> = {};
      if (spec.about !== undefined && !existing.about) data.about = spec.about;
      if (spec.foundedYear !== undefined && !existing.foundedYear) data.foundedYear = spec.foundedYear;
      if (spec.linkedinUrl !== undefined && !existing.linkedinUrl) data.linkedinUrl = spec.linkedinUrl;
      if (spec.twitterUrl !== undefined && !existing.twitterUrl) data.twitterUrl = spec.twitterUrl;
      if (spec.facebookUrl !== undefined && !existing.facebookUrl) data.facebookUrl = spec.facebookUrl;
      if (spec.teamSize !== undefined && !existing.teamSize) data.teamSize = spec.teamSize;
      if (spec.companyTier !== undefined && !existing.companyTier) data.companyTier = spec.companyTier;

      const merge = (a: string[] | undefined, b: string[] | undefined) =>
        Array.from(new Set([...(a ?? []), ...(b ?? [])]));
      if (spec.benefits) {
        const merged = merge(existing.benefits, spec.benefits);
        if (merged.length > existing.benefits.length) data.benefits = merged;
      }
      if (spec.techStack) {
        const merged = merge(existing.techStack, spec.techStack);
        if (merged.length > existing.techStack.length) data.techStack = merged;
      }
      if (spec.evDomains) {
        const merged = merge(existing.evDomains, spec.evDomains);
        if (merged.length > existing.evDomains.length) data.evDomains = merged;
      }

      if (Object.keys(data).length === 0) {
        // Already enriched — no-op.
        continue;
      }

      await db.company.update({
        where: { id: existing.id },
        data,
      });
      console.log(`   ✓ ${existing.name} (${spec.slug}) — ${Object.keys(data).join(", ")}`);
      touched += 1;
    }
  }

  console.log(
    `\n✅ All batches done. Enriched ${touched} compan${touched === 1 ? "y" : "ies"}${missing > 0 ? ` · ${missing} missing slugs (skipped)` : ""}.`,
  );
  console.log("   Add the next batch by appending a BATCH_02 const + pushing it into the allBatches array.");
}

main()
  .catch((err) => {
    console.error("✗ Company enrichment failed:", err);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
